            ['term' => 'Vegetative Symptoms', 'definition' => 'Somatic disturbances of bodily maintenance functions in depression, including sleep disruption, appetite alterations, weight shifts, and energy loss.'],
            ['term' => 'Psychomotor Retardation', 'definition' => 'A visible, generalized slowing of physical speech, movement, and cognitive processing, characteristic of severe depressive states.'],
